  "failed_approaches": [
    {
      "id": "FAM:SF20",
      "what_failed": "Predicting the magnitude of structural change (V2) or its impact due to player absence using LOO simulation.",
      "why": "LIM:small_sample; V2a Spearman +0.288, p=0.077, CI [-0.244, +0.667] FAIL; V2b partial +0.253, p=0.115, CI [-0.262, +0.615] FAIL."
    },
    {
      "id": "FAM:SF-APPS-009",
      "what_failed": "Comparing V4 vs V5 player routing direct scoring.",
      "why": "A_unanswerable (question not answerable with the data or design); LIM:small_sample; 0 scoreable of 8 divergences; V5 mostly routed to 'team' rather than a player."
    },
